<?php
namespace App\Http\Controllers;
use App\Models\AdvanceSalary; use App\Models\EmployeeBankAccount; use App\Models\EmployeeDetails; use App\Models\HrAttendanceException; use App\Models\HrPayrollPreflightRun; use App\Models\Leave; use App\Models\PayrollEmployeeSetup; use App\Models\User; use Carbon\Carbon; use Illuminate\Http\Request;
class HrPayrollPreflightController extends AccountBaseController { public function index(Request $request){$this->pageTitle = 'Payroll preflight';abort_403(!in_array(user()->permission('add_payroll'),['all'],true));$period=$request->input('period',now()->format('Y-m'));$start=Carbon::createFromFormat('Y-m',$period)->startOfMonth();$end=$start->copy()->endOfMonth();$employees=User::allEmployees(null,false,'all',user()->company_id);$ids=$employees->pluck('id');$summary=['employees'=>$ids->count(),'missing_bank_account'=>$ids->diff(EmployeeBankAccount::whereIn('employee_id',$ids)->pluck('employee_id'))->count(),'expired_documents'=>EmployeeDetails::whereIn('user_id',$ids)->where(function($q){$q->whereDate('iqama_expiry_date','<',today())->orWhereDate('national_id_expiry_date','<',today())->orWhereDate('passport_expiry_date','<',today());})->count(),'unpaid_leave_days'=>Leave::whereIn('user_id',$ids)->whereBetween('leave_date',[$start,$end])->where('status','approved')->whereHas('type',fn($q)=>$q->where('paid',0))->count(),'approved_overtime_exceptions'=>HrAttendanceException::whereIn('employee_id',$ids)->where('type','overtime')->where('status','approved')->whereBetween('attendance_date',[$start,$end])->count(),'pending_attendance_exceptions'=>HrAttendanceException::whereIn('employee_id',$ids)->where('status','pending')->count(),'pending_advances'=>AdvanceSalary::whereIn('employee_id',$ids)->where('status','pending')->count(),'salary_setup_changes'=>PayrollEmployeeSetup::whereIn('user_id',$ids)->whereBetween('updated_at',[$start,$end])->count()];$this->run=HrPayrollPreflightRun::firstOrCreate(['company_id'=>user()->company_id,'period'=>$period],['summary'=>$summary]);if($this->run->status==='open')$this->run->update(['summary'=>$summary]);$this->period=$period;return view('hr-payroll-preflight.index',$this->data);} public function approve(HrPayrollPreflightRun $run){abort_403(!in_array(user()->permission('add_payroll'),['all'],true)||$run->company_id!==user()->company_id);$run->update(['status'=>'approved','approved_by'=>user()->id,'approved_at'=>now()]);return redirect()->route('hr-payroll-preflight.index',['period'=>$run->period])->with('success','Payroll preflight approved and locked.');}}
